const respuesta = pm.response.json();

if (pm.response.code === 200 && respuesta.token) {
    if (respuesta.usuario.rol === "administrador") {
        pm.collectionVariables.set("adminToken", respuesta.token);
    } else {
        pm.collectionVariables.set("userToken", respuesta.token);
    }
}

if (pm.response.code === 200) {
  const respuesta = pm.response.json();
  if (respuesta.token) pm.collectionVariables.set('token', respuesta.token);
  if (respuesta.usuario?.id_usuario) pm.collectionVariables.set('usuarioId', String(respuesta.usuario.id_usuario));
}
